package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Boolean;
    in attribute io_1 : Boolean;
    in attribute io_2 : Real;
    attribute previousAnyPIR : Boolean := false;
    attribute isLighting : Boolean := false;
    attribute todayCount : Integer := 0;
    attribute illuminatedOnTimeMs : Integer := 0;
    perform action tick {
      first start;
      then assign isLighting := ((io_2 < 300.0) and (((io_0) or (io_1))));
      then if ((((io_0) or (io_1))) and ((not previousAnyPIR))) {
        first start;
        then assign todayCount := todayCount + 1;
      }
      then if isLighting {
        first start;
        then assign illuminatedOnTimeMs := illuminatedOnTimeMs + 10;
      }
      then assign previousAnyPIR := ((io_0) or (io_1));
    }
    out attribute io_3 : Real = (if isLighting ? 255.0 else 0.0);
    out attribute io_4 : Integer = todayCount;
    out attribute io_5 : Real = (if isLighting ? 255.0 else 0.0);
    out attribute serial_0_trigger : Boolean = (if isLighting ? true else false);
    out attribute serial_0_value_0 : Integer = illuminatedOnTimeMs;
  }
  part system : Controller;
}
